"""Named, parameterized training-state statements. Used within Store transactions."""
QUERIES = {'sessions_1': 'SELECT payload FROM sessions WHERE id<>?', 'sessions_2': 'SELECT payload,created_at FROM sessions ORDER BY created_at DESC,rowid DESC', 'requests_3': 'INSERT INTO requests VALUES(?,?,?,?)', 'actions_4': "SELECT receipt FROM actions WHERE session_id=? AND json_extract(receipt,'$.action')<>'HOLD' ORDER BY revision", 'actions_5': 'SELECT a.receipt,n.note,n.mistake FROM actions a LEFT JOIN notes n ON n.session_id=a.session_id AND n.revision=a.revision WHERE a.session_id=? ORDER BY a.revision LIMIT ? OFFSET ?', 'actions_6': 'SELECT receipt FROM actions WHERE session_id=? ORDER BY revision DESC LIMIT 1', 'requests_7': 'SELECT * FROM requests WHERE id=?', 'sessions_8': 'SELECT payload FROM sessions', 'actions_9': 'SELECT count(*) FROM actions WHERE session_id=?', 'notes_10': 'SELECT count(*) FROM notes WHERE session_id=? AND mistake=1', 'actions_11': 'INSERT INTO actions VALUES(?,?,?,?)', 'sessions_12': 'SELECT created_at FROM sessions WHERE id=?', 'notes_13': 'INSERT INTO notes(session_id,revision,note,mistake) VALUES(?,?,?,?) ON CONFLICT(session_id,revision) DO UPDATE SET note=excluded.note,mistake=excluded.mistake,updated_at=CURRENT_TIMESTAMP', 'notes_14': 'SELECT note,mistake FROM notes WHERE session_id=? AND revision=?', 'actions_15': 'SELECT 1 FROM actions WHERE session_id=? AND revision=?'}

def query(transaction,name,parameters=()):
    return transaction.execute(QUERIES[name],parameters)
